package api

// The msgp marshallers for the types below live in telemetry_batch_gen.go,
// generated by the //pkg/trace/api:telemetry_batch_gen Bazel target.
// Regenerate with: bazel run //pkg/trace/api:telemetry_batch_gen

// AgentTelemetryBatch is the top-level msgpack envelope for batched telemetry
// payloads the agent forwards to the backend telemetry intake.
type AgentTelemetryBatch struct {
	RequestType string                 `msg:"request_type"`
	Payload     *AgentTelemetryPayload `msg:"payload"`
}

// AgentTelemetryPayload wraps the list of buffered telemetry events.
type AgentTelemetryPayload struct {
	Events []*AgentTelemetryEvent `msg:"events"`
}

// AgentTelemetryEvent is a single buffered telemetry HTTP request, captured
// as its original headers and body.
type AgentTelemetryEvent struct {
	Headers map[string]string `msg:"headers"`
	Content []byte            `msg:"content"`
}
